        'rot90': (lambda r,c:(c,h-1-r), lambda: [[panel[h-1-c][r] for c in range(h)] for r in range(w)]),
        'rot180': (lambda r,c:(h-1-r,w-1-c), lambda: [[panel[h-1-r][w-1-c] for c in range(w)] for r in range(h)]),
