        'flip_h': (lambda r,c:(r,w-1-c), lambda: [[panel[r][w-1-c] for c in range(w)] for r in range(h)]),
        'flip_v': (lambda r,c:(h-1-r,c), lambda: [[panel[h-1-r][c] for c in range(w)] for r in range(h)]),
        'transpose': (lambda r,c:(c,r), lambda: [[panel[c][r] for r in range(h)] for c in range(w)]),
        'anti': (lambda r,c:(w-1-c,h-1-r), lambda: [[panel[h-1-c][w-1-r] for r in range(h)] for c in range(w)]),
    }
    def sign(x): return (x > 0) - (x < 0)
    for coord, make in transforms.values():
        loc = {v: coord(*inside[v][0]) for v in colors}
        good = True
        for i, a in enumerate(colors):
            for b in colors[i+1:]:
                dr1, dc1 = loc[b][0]-loc[a][0], loc[b][1]-loc[a][1]
